+            assertThat(page.getByText("Showing 500 of 500", new Page.GetByTextOptions().setExact(true))).isVisible();
+            page.waitForURL(url -> URI.create(url).getQuery() == null);
+        }
+    }
+
+    private static void toggleStatus(Page page, String status) {
+        Locator input = page.locator("vaadin-multi-select-combo-box input");
+        input.click();
+        page.getByRole(AriaRole.OPTION, new Page.GetByRoleOptions().setName(status).setExact(true)).click();
+        input.press("Escape");
+    }
+
+    private static String decodedQuery(Page page) {
+        return URLDecoder.decode(URI.create(page.url()).getRawQuery(), StandardCharsets.UTF_8);
+    }
